function nearestZero(grid: number[][]): number[][] {
  const m = grid.length, n = grid[0].length;
  const dist = (sr: number, sc: number): number => {
    const seen = new Set<number>([sr * n + sc]);
    let level = [[sr, sc]];
    for (let d = 0; ; d++) {
      const next: number[][] = [];
      for (const [r, c] of level) {
        if (grid[r][c] === 0) return d;
        for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const i = r + dr, j = c + dc;
          if (i >= 0 && i < m && j >= 0 && j < n && !seen.has(i * n + j)) { seen.add(i * n + j); next.push([i, j]); }
        }
      }
      level = next;
    }
  };
  return grid.map((row, r) => row.map((_, c) => dist(r, c)));
}

