function nearestZero(grid: number[][]): number[][] {
  const m = grid.length, n = grid[0].length;
  const out = grid.map(row => row.map(v => (v === 0 ? 0 : -1)));
  const queue: number[][] = [];
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (out[r][c] === 0) queue.push([r, c]);
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const i = r + dr, j = c + dc;
      if (i >= 0 && i < m && j >= 0 && j < n && out[i][j] === -1) {
        out[i][j] = out[r][c] + 1;
        queue.push([i, j]);
      }
    }
  }
  return out;
}

