function nearestZero(grid: number[][]): number[][] {
  const m = grid.length, n = grid[0].length, BIG = m + n;
  const d = grid.map(row => row.map(v => (v === 0 ? 0 : BIG)));
  for (let r = 0; r < m; r++)
    for (let c = 0; c < n; c++) {
      if (r > 0) d[r][c] = Math.min(d[r][c], d[r - 1][c] + 1);
      if (c > 0) d[r][c] = Math.min(d[r][c], d[r][c - 1] + 1);
    }
  for (let r = m - 1; r >= 0; r--)
    for (let c = n - 1; c >= 0; c--) {
      if (r < m - 1) d[r][c] = Math.min(d[r][c], d[r + 1][c] + 1);
      if (c < n - 1) d[r][c] = Math.min(d[r][c], d[r][c + 1] + 1);
    }
  return d;
}

